/**
 * Hand-written mirrors of the scanner's JSON output. The Swift `Codable` types in
 * `apple/Sources/ExpoModulesScanner` are the source of truth; these are kept in sync by hand, which
 * is why each command carries a `schemaVersion` the wrapper checks at runtime.
 */
/** The JS `typeof` category a boundary type reports, mirroring `JSType`. */
export type JSType = 'undefined' | 'object' | 'boolean' | 'number' | 'bigint' | 'string' | 'symbol' | 'function';
/**
 * A boundary type as a tagged tree, mirroring `TypeNode`. Discriminate on `kind`.
 *
 * `unknown` carries no `typeof`, and an `optional` reports its *wrapped* node's category, so
 * `(Int, String)?` (an optional around an unknown) has none either. Every other node always has one.
 * The absent (`undefined`) case is carried by the `optional` wrapper itself rather than by its
 * wrapped node.
 */
export type TypeNode = {
    kind: 'primitive';
    typeof: JSType;
    name: string;
} | {
    kind: 'optional';
    typeof?: JSType;
    wrapped: TypeNode;
} | {
    kind: 'array';
    typeof: JSType;
    element: TypeNode;
} | {
    kind: 'dictionary';
    typeof: JSType;
    key: TypeNode;
    value: TypeNode;
} | {
    kind: 'promise';
    typeof: JSType;
    value: TypeNode;
} | {
    kind: 'function';
    typeof: JSType;
    parameters: TypeNode[];
    /** Absent for a `Void` result. */
    returns?: TypeNode;
    async: boolean;
    throws: boolean;
}
/**
 * Any other named type. When `refKind` is present, `name` is the declaration's qualified name,
 * equal to the `name` of the matching entry in the surface (`Encoding` written in `Options` reports
 * `Options.Encoding`). Otherwise it is the spelling as written, which may be qualified.
 *
 * `refKind` says which of this surface's arrays declares that name, so you don't have to look it
 * up. It is absent when the scan declares no such type: a platform convertible (`CGPoint`, `URL`)
 * or a type from another module, which your own catalog resolves.
 *
 * `typeof` follows the resolved kind, so a raw-value enum reports `string` or `number` rather than
 * `object`. Only the scanner can determine that, since it comes from the declaration's `rawType`.
 */
 | {
    kind: 'ref';
    typeof: JSType;
    name: string;
    refKind?: 'record' | 'sharedObject' | 'enum' | 'union';
}
/** A type the scanner couldn't interpret; `text` is its source spelling. */
 | {
    kind: 'unknown';
    text: string;
};
/**
 * An Apple OS the scanner attributes declarations to, spelled as `os(...)` spells it. The casing is
 * part of the output contract, so consumers with a lowercase convention must fold the case themselves.
 */
export type ScannedPlatform = 'iOS' | 'macOS' | 'tvOS' | 'watchOS' | 'visionOS';
/** One Apple OS that builds a declaration in the `scan-exports` output. */
export interface ExportedPlatform {
    name: ScannedPlatform;
    /**
     * The version spelled in `@available` (`17.0` in `@available(iOS 17.0, *)`), or absent when no
     * attribute on the declaration or its enclosing types names one. The latest version wins when
     * several do.
     */
    introduced?: string;
    /**
     * How the declaration's own `@available` attributes deprecate it on this OS, or absent when they
     * don't. Enclosing types are not read: a member of a deprecated type is not itself reported as
     * deprecated.
     */
    deprecated?: ExportedDeprecation;
}
/**
 * A deprecation from `@available`: `@available(*, deprecated, ...)` on every OS, or
 * `@available(iOS, deprecated: 16, obsoleted: 18, ...)` on one. Each field is absent when not
 * written. When a platform has its own attribute and a `*` one also applies, they combine and the
 * platform's fields win.
 */
export interface ExportedDeprecation {
    /** The version from `deprecated: 16`; absent for a bare `deprecated`. */
    since?: string;
    /**
     * The version from `obsoleted: 18`, from which the declaration is no longer available. A
     * declaration that is only obsoleted is still reported as deprecated.
     */
    obsoleted?: string;
    /** The `message:` text. */
    message?: string;
    /**
     * The `renamed:` text: the Swift name of the replacement, as written (`newName`,
     * `other(value:)`). It is not resolved to a JS name.
     */
    renamed?: string;
}
/**
 * The parts of a declaration or member that say where and to whom it is available. A declaration no
 * platform builds is not reported, so `platforms` is never empty.
 */
export interface ExportedAvailability {
    /** The OSes that build it: its `#if` conditions hold and no `@available` makes it unavailable. */
    platforms: ExportedPlatform[];
}
/** The spelled Swift access modifier of a declaration. */
export interface ExportedAccess {
    /**
     * `open`, `public`, `package`, `internal`, `fileprivate`, or `private`, or absent when none is
     * written. A setter-only modifier like `private(set)` is not reported.
     */
    accessLevel?: string;
}
/** One parameter of a `@JS` function or `@JS init`. */
export interface ExportedParameter {
    /** The argument label, or `_` when unlabeled. */
    label: string;
    /** The internal parameter name. */
    name: string;
    type: TypeNode;
    /** True when the caller may omit it: a default value or an optional type. */
    optional: boolean;
    /** The default value as Swift source text (`1`, `"x"`, `.fast`), absent when none is written. */
    defaultValue?: string;
}
/** One `@JS func` on a module or shared object. */
export interface ExportedFunction extends ExportedAccess, ExportedAvailability {
    /**
     * The Swift declaration name. A function with `.withAsync("x")` has two entries with this name.
     */
    name: string;
    /**
     * The JS name it binds under: the `@JS("x")` override, else `name`. The second entry of a function
     * with `.withAsync("x")` binds under `x`.
     */
    jsName: string;
    parameters: ExportedParameter[];
    /** Absent for a `Void` return. */
    returns?: TypeNode;
    async: boolean;
    throws: boolean;
    static: boolean;
}
/** One `@JS var` on a module or shared object. */
export interface ExportedProperty extends ExportedAccess, ExportedAvailability {
    name: string;
    jsName: string;
    /** Absent when the type isn't determinable syntactically; the macro binds it getter-only. */
    type?: TypeNode;
    readonly: boolean;
    static: boolean;
    /** The initial value of a stored property as Swift source text, absent when none is written. */
    defaultValue?: string;
}
/** One `@Record` property: a data slot, not a JS accessor. */
export interface ExportedRecordProperty extends ExportedAccess, ExportedAvailability {
    name: string;
    type: TypeNode;
    /** Optional-typed. */
    optional: boolean;
    /** Whether JS must supply it: neither defaulted nor optional. */
    required: boolean;
    /** The default value as Swift source text, absent when none is written. */
    defaultValue?: string;
}
/** An `@ExpoModule` type and its `@JS` surface. */
export interface ExportedModule extends ExportedAccess, ExportedAvailability {
    /** The Swift class name. A module is always declared at file scope. */
    name: string;
    /** The JS module name: `@ExpoModule("Foo")` override, else the class name. */
    jsName: string;
    functions: ExportedFunction[];
    properties: ExportedProperty[];
    events: ExportedEvent[];
    /**
     * The classes listed in `@ExpoModule(classes: [...])`, in source order. Each is reachable from JS
     * as a member of the module.
     */
    classes: ExportedClass[];
    /** Absolute source path. */
    file: string;
}
/** One entry of `@ExpoModule(classes: [...])`. */
export interface ExportedClass {
    /**
     * The `name` of the matching shared object, which is qualified when the class is nested
     * (`Outer.Statement`). The Swift name as spelled in the argument when the scan found no shared
     * object with this name.
     */
    name: string;
    /**
     * The name of the module member JS reads the class from: the matching shared object's `jsName`.
     * Absent when the scan found no shared object with this name, for example a class defined outside
     * the scanned paths.
     */
    jsName?: string;
}
/** One `@Event var`: a typed event JS listens for by name, rather than calls. */
export interface ExportedEvent extends ExportedAccess, ExportedAvailability {
    /** The Swift property name, e.g. `onStatusChange`. */
    name: string;
    /**
     * The name JS listens under: the `@Event("x")` override, else `name` with a conventional `on`
     * prefix stripped and decapitalized (`onStatusChange` -> `statusChange`).
     */
    jsName: string;
    /** The payload type, absent for a no-payload `() -> Void` event. */
    payload?: TypeNode;
    /** `@Event(sync: true)`, dispatching inline on the JS thread instead of scheduling. */
    sync: boolean;
}
/** The `@JS init` of a shared object: the constructor JS calls with `new`. */
export interface ExportedInitializer extends ExportedAccess, ExportedAvailability {
    parameters: ExportedParameter[];
}
/** A `@SharedObject` type: a JS class with an optional constructor plus its `@JS` members. */
export interface ExportedSharedObject extends ExportedAccess, ExportedAvailability {
    /** The Swift class name, qualified with the types it is nested in (`Outer.Player`). */
    name: string;
    /**
     * The JS class name: `@SharedObject("Foo")` override, else the class name without the enclosing
     * types.
     */
    jsName: string;
    /**
     * The `@JS init`, or absent when there's none. At most one constructor. Not named `constructor`,
     * which every JS object inherits.
     */
    initializer?: ExportedInitializer;
    functions: ExportedFunction[];
    properties: ExportedProperty[];
    events: ExportedEvent[];
    file: string;
}
/** A `@Record` type and its properties. */
export interface ExportedRecord extends ExportedAccess, ExportedAvailability {
    /** The Swift type name, qualified with the types it is nested in (`Outer.Options`). */
    name: string;
    properties: ExportedRecordProperty[];
    file: string;
}
/**
 * One case of a reported enum.
 *
 * What `rawValue` carries depends on the enum's raw type:
 * - `String`: always present, and decoded (`case active = "act"` reports `act`, unquoted). A case
 *   writing none takes its own name, so nothing is left to derive.
 * - an integer type: present only where written, as source text (`1`, `1 << 3`), since the value may
 *   be an expression a syntactic scan cannot evaluate. Swift also continues from the preceding case's
 *   value (`case a = 1; case b` makes `b` 2), and that carry is yours to apply.
 * - no raw type: always absent, since the enum has no raw values.
 */
export interface ExportedEnumCase extends ExportedAvailability {
    /** The case name as declared. */
    name: string;
    /** The raw value, decoded for a string and verbatim source text otherwise, or absent per the rule above. */
    rawValue?: string;
}
/**
 * An `Enumerable` enum: a type crossing the boundary as its raw value rather than as an object.
 * Detected by conformance, not by a macro attribute, so it carries no `jsName`.
 */
export interface ExportedEnum extends ExportedAccess, ExportedAvailability {
    /** The Swift enum name, qualified with the types it is nested in (`Options.Encoding`). */
    name: string;
    /** The raw value type as written, absent for a bare `Enumerable` conformance with no raw type. */
    rawType?: TypeNode;
    cases: ExportedEnumCase[];
    file: string;
}
/**
 * One alternative a `@Union` may hold. Not a member in the sense a module or shared object has members
 * (functions, properties, events).
 */
export interface ExportedUnionMember extends ExportedAvailability {
    /** The Swift case name. Swift-side only: discrimination is structural, so it never reaches JS. */
    name: string;
    /** The associated value's type: what this alternative decodes from. */
    type: TypeNode;
}
/**
 * A `@Union` enum: a typed union of its members' payload types (`A | B | C`).
 *
 * `members` is ordered, and the order is part of the contract: decode takes the first payload that
 * succeeds, so where two shapes overlap (`Int` and `Double`, two compatible records) the earlier one
 * wins. Reordering them describes a different union than the one the module runs.
 */
export interface ExportedUnion extends ExportedAccess, ExportedAvailability {
    /** The Swift enum name, qualified with the types it is nested in (`Options.Value`). */
    name: string;
    members: ExportedUnionMember[];
    file: string;
}
/** The exported types grouped by kind. */
export interface ExportedSurface {
    modules: ExportedModule[];
    sharedObjects: ExportedSharedObject[];
    records: ExportedRecord[];
    enums: ExportedEnum[];
    unions: ExportedUnion[];
}
/** A `#if` condition the scan couldn't answer statically. */
export interface ScanWarning {
    message: string;
    file: string;
    line: number;
}
/** Counts describing how much work a scan did. */
export interface ScanStats {
    /** `.swift` files the walk found and read. */
    filesScanned: number;
    /** Of those, how many matched the pre-filter (a macro attribute or a scanned conformance). */
    filesParsed: number;
    /** Wall-clock duration of the scan, in milliseconds. */
    durationMs: number;
}
/** One module in the `scan-modules` output. */
export interface ScannedModule {
    name: string;
    /** The resolved JS name: the `@ExpoModule("Foo")` override, else the class name. */
    jsName: string;
    /**
     * The spelled access level, or `internal` when none is written. The generated provider references
     * the class from the app target, so anything below `public` can't be registered.
     */
    accessLevel: string;
    /**
     * The OSes whose builds include this class, resolved from the enclosing `#if` conditions. An
     * unconditional module lists every OS. Empty means no build is known to include it, so don't
     * register it.
     */
    platforms: ScannedPlatform[];
    file: string;
}
/** The `scan-modules` result. */
export interface ScanModulesResult {
    schemaVersion: number;
    modules: ScannedModule[];
    warnings: ScanWarning[];
    stats: ScanStats;
}
/** The `scan-exports` result. */
export interface ScanExportsResult {
    schemaVersion: number;
    exports: ExportedSurface;
    stats: ScanStats;
}
/**
 * The output schema versions this package was written against. The wrapper compares these to the
 * `schemaVersion` in each report and throws on a mismatch, so a binary/wrapper version skew surfaces
 * as a clear error instead of silently misread fields.
 */
export declare const SUPPORTED_SCAN_MODULES_SCHEMA_VERSION = 2;
export declare const SUPPORTED_SCAN_EXPORTS_SCHEMA_VERSION = 8;
